  "acc.removeQ": "Удалить это устройство?",
  "acc.removeBody": "{who} будет удалён из списка и сразу потеряет доступ.\n\nЗапись об устройстве стирается, а не отключается, и устройство сможет подключиться снова по новому приглашению. Уже подписанные с него осмотры не затрагиваются — в них записана подпись, а не устройство.",
