  "acc.removeFromList": "Удалить из списка",
  "acc.thisDeviceLc": " · это устройство",
  "acc.lastMaster": "\n\nЭто единственный капитан на судне, поэтому его роль нельзя изменить и его нельзя отключить — не останется никого, кто мог бы это отменить. Сначала сделайте капитаном другое устройство, тогда это можно будет менять.",
  "acc.title": "Учётные записи",
  "acc.sub": "Кто может пользоваться журналом этого судна",
  "acc.imoRequired": "Нужен номер ИМО судна",
  "acc.imoBody": "Учётные записи выдаются для судна, а судно определяется номером ИМО. Сначала укажите его в Настройки → Судно.",
  "acc.subMaster": "Выдача, отзыв и одобрение",
  "acc.subCrew": "Кто на борту этого судна",
  "acc.rankUnknown": "Выясняем права этого устройства",
  "acc.rankUnknownBody": "Учётные записи откроются, когда судно подтвердит роль этого устройства. Если так и остаётся, устройство ещё не подключено — см. карточку «Это устройство» вверху Настроек.",
  "acc.readOnly": "{role} — только просмотр",
  "acc.readOnlyBody": "Учётные записи, одобрение и роли — у капитана. Ваше устройство — его имя, роль и одобрение — в Настройки → Это устройство.",
  "acc.invitationsN": "Приглашения ({n})",
