  "acc.noInvites": "Учётные записи ещё не выдавались.",
  "acc.revoked": "Отозван",
  "acc.unused": "Не использован",
  "acc.olderBody": "Тот же человек с той же ролью и таким же устройством подключился снова — с другого адреса браузера, после очистки браузера или с переустановленного телефона. Остаётся последнее активное (это устройство — всегда). Сервер сам отключает такие подключения через три дня без использования; если открыть снова — оно вернётся.",
