  "acc.renameTitle": "Переименовать устройство",
  "acc.renameNote": "Как это устройство называется в списке и на его карточке «Это устройство». Для общего компьютера, который переходит из рук в руки при каждой смене экипажа, укажите должность — «Третий помощник».",
  "acc.renameSignDevice": "Это судно подписывает осмотры учётной записью устройства, поэтому именно это имя будет стоять в следующем обходе, подписанном на этом устройстве, и в его отчёте. Переименуйте при смене экипажа — подпись сразу изменится. Уже подписанные осмотры сохраняют прежнее имя.",
  "acc.renameSignCrew": "На подписи это не влияет — подписывающего выбирают из списка экипажа при подписании обхода, а уже подписанные осмотры сохраняют своё имя.",
