  "ins.scanRequired": "На этом судне перед подписью осмотра нужно отсканировать QR-этикетку позиции — это подтверждает, что осмотр сделан у оборудования. Подойдите к позиции и отсканируйте этикетку приложением. Сканирование действует {n} мин; ввод кода вручную не засчитывается.",
